## 3) **Copy Constructor**  
Creates a new object as a copy of an existing object.

```cpp
#include <iostream>
using namespace std;

class Box {
public:
    int w, h;
    // Parameterized constructor
    Box(int ww = 0, int hh = 0) : w(ww), h(hh) {
        cout << "Box created (" << w << "x" << h << ")\n";
    }
    // Copy constructor
    Box(const Box &b) : w(b.w), h(b.h) {
        cout << "Copy constructor called\n";
    }
    void show() const {
        cout << "Box: " << w << " x " << h << '\n';
    }
};

int main() {
    Box b1(3,4);
    Box b2 = b1;   // copy constructor called
    b2.show();
    return 0;
}
```

