## 4) **Constructor Overloading (Multiple Constructors)**  
Same name, different parameter lists.

```cpp
#include <iostream>
using namespace std;

class Date {
    int d, m, y;
public:
    Date() : d(1), m(1), y(2000) { cout << "Default date\n"; }
    Date(int dd, int mm) : d(dd), m(mm), y(2000) { cout << "Two-arg date\n"; }
    Date(int dd, int mm, int yy) : d(dd), m(mm), y(yy) { cout << "Three-arg date\n"; }
    void show() const {
        cout << d << '/' << m << '/' << y << '\n';
    }
};

int main() {
    Date a;             // default
    Date b(5, 10);      // two-arg
    Date c(7, 11, 2025);// three-arg
    a.show(); b.show(); c.show();
    return 0;
}
```

