## 6) **Initializer List (important for const/ref members & base-class init)**  
Use when you must initialize const/reference members or base subobject.

```cpp
#include <iostream>
using namespace std;

class Base {
public:
    int id;
    Base(int i) : id(i) { cout << "Base(" << id << ") constructed\n"; }
};

class Example {
    const int c;       // must be initialized
    int &ref;          // reference must be initialized
    Base baseObj;      // initialize base-like member via list
public:
    // initializer list initializes c, ref, baseObj
    Example(int value, int &r)
        : c(value), ref(r), baseObj(value + 100) {
        cout << "Example constructed, c=" << c << ", ref=" << ref << '\n';
    }
    void show() const {
        cout << "c=" << c << ", ref=" << ref << ", base.id=" << baseObj.id << '\n';
    }
};

int main() {
    int x = 10;
    Example e(7, x);
    e.show();
    return 0;
}
```

