    Buffer(int size) : n(size) {
        arr = new int[n];
        cout << "Buffer allocated of size " << n << '\n';
    }
    ~Buffer() {
        delete[] arr;
        cout << "Buffer freed\n";
    }
    void set(int i, int v) { if (i>=0 && i<n) arr[i]=v; }
    int get(int i) const { return arr[i]; }
};

int main() {
    {
        Buffer b(5);
        b.set(0, 42);
        cout << "b[0] = " << b.get(0) << '\n';
    } // destructor called here
    cout << "After block\n";
    return 0;
}
```

